<script setup lang="ts">
import { ApiError } from '~/plugins/api.client'
import { adminErrorMessage, adminFieldErrors, useAdministration, type AdminUser } from '~/composables/useAdministration'
import { formatDateTime } from '~/utils/presentation'

definePageMeta({ middleware: 'auth' })
const admin = useAdministration()
const session = useSession()
const router = useRouter()
const route = useRoute()
const users = ref<AdminUser[]>([])
const meta = ref({ current_page: 1, last_page: 1, per_page: 25, total: 0 })
const loading = ref(true)
const error = ref('')
const pending = ref(false)
const createOpen = ref(false)
const editTarget = ref<AdminUser | null>(null)
const passwordTarget = ref<AdminUser | null>(null)
const authorityTarget = ref<AdminUser | null>(null)
const deactivateTarget = ref<AdminUser | null>(null)
const remediation = ref<{ user: AdminUser; message: string } | null>(null)
const fields = ref<Record<string, string[]>>({})
const createForm = reactive({ display_name: '', email: '', password: '', is_system_admin: false })
const identityForm = reactive({ display_name: '', email: '' })
const password = ref('')
const replacementId = ref('')
const q = computed({ get: () => String(route.query.q || ''), set: value => setQuery({ q: value || undefined, page: undefined }) })
const page = computed(() => Math.max(1, Number(route.query.page || 1)))
const perPage = computed({ get: () => [25, 50, 100].includes(Number(route.query.per_page)) ? Number(route.query.per_page) : 25, set: value => setQuery({ per_page: value === 25 ? undefined : value, page: undefined }) })
const isAdmin = computed(() => session.user.value?.is_system_admin || false)
const rangeText = computed(() => { if (!meta.value.total) return ''; const first = (meta.value.current_page - 1) * meta.value.per_page + 1; return `نمایش ${first} تا ${Math.min(first + users.value.length - 1, meta.value.total)} از ${meta.value.total} کاربر` })
function setQuery(next: Record<string, string | number | undefined>) { router.push({ query: { ...route.query, ...next } }) }
async function load() { if (!isAdmin.value) { users.value = []; loading.value = false; return }; loading.value = true; error.value = ''; try { const result = await admin.listUsers(q.value.trim(), page.value, perPage.value); users.value = result.data; if (result.meta) { meta.value = result.meta; if (page.value > result.meta.last_page) setQuery({ page: result.meta.last_page === 1 ? undefined : result.meta.last_page }) } } catch (caught) { error.value = adminErrorMessage(caught); if (caught instanceof ApiError && caught.status === 403) { users.value = []; await session.refresh(); await navigateTo('/projects') } } finally { loading.value = false } }
function openEdit(user: AdminUser) { editTarget.value = user; Object.assign(identityForm, { display_name: user.display_name, email: user.email }) }
async function mutate(user: AdminUser, data: Record<string, unknown>) { pending.value = true; fields.value = {}; error.value = ''; try { const result = await admin.updateUser(user.id, data as any); users.value = users.value.map(item => item.id === user.id ? result.data : item); if (user.id === session.user.value?.id && ('is_system_admin' in data || data.active === false)) { await session.refresh(); if (!session.user.value?.is_system_admin) await navigateTo('/projects') } } catch (caught) { error.value = adminErrorMessage(caught); fields.value = adminFieldErrors(caught); if (caught instanceof ApiError && caught.status === 409 && data.active === false) remediation.value = { user, message: error.value } } finally { pending.value = false } }
async function create() { pending.value = true; fields.value = {}; error.value = ''; try { await admin.createUser({ ...createForm, email: createForm.email.trim().toLowerCase() }); createForm.password = ''; createOpen.value = false; setQuery({ page: undefined, q: undefined }); await load() } catch (caught) { error.value = adminErrorMessage(caught); fields.value = adminFieldErrors(caught) } finally { pending.value = false } }
async function saveIdentity() { if (!editTarget.value) return; await mutate(editTarget.value, { display_name: identityForm.display_name.trim(), email: identityForm.email.trim().toLowerCase() }); if (!error.value) editTarget.value = null }
async function savePassword() { if (!passwordTarget.value) return; await mutate(passwordTarget.value, { password: password.value }); if (!error.value) { password.value = ''; passwordTarget.value = null } }
async function changeAuthority() { if (!authorityTarget.value) return; await mutate(authorityTarget.value, { is_system_admin: !authorityTarget.value.is_system_admin }); if (!error.value) authorityTarget.value = null }
async function deactivate(remedy?: { unassign: true } | { reassign_to: string }) { const target = remediation.value?.user || deactivateTarget.value; if (!target) return; await mutate(target, remedy ? { active: false, remediation: remedy } : { active: false }); if (!error.value) { deactivateTarget.value = null; remediation.value = null } }
watch(() => [route.query.q, route.query.page, route.query.per_page, isAdmin.value], () => { void load() }, { immediate: true })
</script>

<template>
  <main v-if="isAdmin" class="users-page"><section class="users-toolbar"><div class="users-toolbar__controls"><UInput v-model="q" icon="i-lucide-search" placeholder="جست‌وجوی نام یا ایمیل…" :disabled="loading" /><UButton v-if="q" color="neutral" variant="ghost" size="sm" @click="q = ''">پاک‌کردن</UButton></div><div class="users-toolbar__end"><span v-if="!loading && !error" class="users-range">{{ rangeText }}</span><USelect v-model="perPage" :items="[25, 50, 100]" :disabled="loading" /><UButton size="sm" icon="i-lucide-user-plus" @click="createOpen = true">ایجاد کاربر</UButton></div></section><section v-if="loading" class="users-loading" aria-busy="true"><USkeleton v-for="index in 9" :key="index" class="h-14 w-full" /></section><section v-else-if="error" class="users-state"><UAlert color="error" variant="subtle" title="بارگیری کاربران انجام نشد" :description="error"><template #actions><UButton size="xs" color="error" variant="outline" @click="load">تلاش مجدد</UButton></template></UAlert></section><section v-else-if="!users.length" class="users-state"><h2>{{ q ? 'کاربری با این نام یا ایمیل پیدا نشد.' : 'کاربری برای نمایش وجود ندارد.' }}</h2><UButton v-if="q" size="sm" color="neutral" variant="ghost" @click="q = ''">پاک‌کردن جست‌وجو</UButton><UButton v-else size="sm" @click="createOpen = true">ایجاد کاربر</UButton></section><div v-else class="users-table-wrap"><table class="users-table"><thead><tr><th>کاربر</th><th>شناسه</th><th>دسترسی سیستمی</th><th>وضعیت</th><th>آخرین تغییر</th><th><span class="sr-only">اقدام</span></th></tr></thead><tbody><tr v-for="user in users" :key="user.id" :class="{ 'users-table__inactive': !user.active }"><td><span class="users-table__identity"><strong dir="auto">{{ user.display_name }}</strong><TechnicalValue :value="user.email" /><UBadge v-if="user.id === session.user.value?.id" color="neutral" variant="subtle">حساب شما</UBadge></span></td><td><TechnicalValue :value="user.id" /></td><td><RoleBadges :system-admin="user.is_system_admin" /><span v-if="!user.is_system_admin" class="users-table__none">بدون مدیریت سراسری</span></td><td><UBadge :color="user.active ? 'success' : 'warning'" variant="subtle">{{ user.active ? 'فعال' : 'غیرفعال' }}</UBadge></td><td><time :datetime="user.updated_at">{{ formatDateTime(user.updated_at) }}</time></td><td class="users-table__actions"><UButton size="xs" color="neutral" variant="ghost" @click="openEdit(user)">ویرایش مشخصات</UButton><UButton size="xs" color="neutral" variant="ghost" @click="passwordTarget = user">تغییر رمز</UButton><UButton size="xs" color="neutral" variant="ghost" @click="authorityTarget = user">{{ user.is_system_admin ? 'لغو مدیر سراسری' : 'اعطای مدیر سراسری' }}</UButton><UButton v-if="user.active" size="xs" color="error" variant="ghost" @click="deactivateTarget = user">غیرفعال‌کردن</UButton></td></tr></tbody></table></div><footer v-if="meta.last_page > 1" class="users-pagination"><UButton size="sm" color="neutral" variant="outline" :disabled="loading || meta.current_page <= 1" @click="setQuery({ page: meta.current_page - 1 })">صفحهٔ قبل</UButton><span>{{ meta.current_page }} / {{ meta.last_page }}</span><UButton size="sm" color="neutral" variant="outline" :disabled="loading || meta.current_page >= meta.last_page" @click="setQuery({ page: meta.current_page + 1 })">صفحهٔ بعد</UButton></footer></main>
  <main v-else class="users-state users-state--blocked"><UAlert color="warning" variant="subtle" title="مدیریت کاربران در دسترس نیست" description="فقط مدیر سراسری می‌تواند حساب‌های کاربری سیستم را مدیریت کند."><template #actions><UButton to="/projects" size="xs" color="neutral" variant="outline">پروژه‌ها</UButton></template></UAlert></main>
  <UModal :open="createOpen" title="ایجاد کاربر" description="این کاربر دعوت‌نامه یا نقش پروژه دریافت نمی‌کند." @update:open="value => { if (!pending) createOpen = value }"><template #body><UAlert v-if="error" color="error" variant="subtle" :description="error" class="mb-4" /><form class="users-form" @submit.prevent="create"><UFormField label="نام نمایشی" :error="fields.display_name?.[0]"><UInput v-model="createForm.display_name" :disabled="pending" /></UFormField><UFormField label="ایمیل" description="با حروف کوچک ذخیره می‌شود." :error="fields.email?.[0]"><UInput v-model="createForm.email" dir="ltr" type="email" :disabled="pending" /></UFormField><UFormField label="رمز عبور اولیه" description="حداقل ۱۲ کاراکتر." :error="fields.password?.[0]"><UInput v-model="createForm.password" dir="ltr" type="password" autocomplete="new-password" :disabled="pending" /></UFormField><label><input v-model="createForm.is_system_admin" type="checkbox" :disabled="pending"> دسترسی مدیر سراسری</label></form></template><template #footer><UButton color="neutral" variant="ghost" :disabled="pending" @click="createOpen = false">انصراف</UButton><UButton :loading="pending" @click="create">ایجاد کاربر</UButton></template></UModal>
  <UModal :open="!!editTarget" title="ویرایش مشخصات" @update:open="value => { if (!value && !pending) editTarget = null }"><template #body><UAlert v-if="editTarget?.active === false" color="warning" variant="subtle" description="این ویرایش حساب را فعال نمی‌کند." class="mb-4" /><form class="users-form" @submit.prevent="saveIdentity"><UFormField label="نام نمایشی" :error="fields.display_name?.[0]"><UInput v-model="identityForm.display_name" :disabled="pending" /></UFormField><UFormField label="ایمیل" :error="fields.email?.[0]"><UInput v-model="identityForm.email" dir="ltr" type="email" :disabled="pending" /></UFormField><UFormField label="شناسه"><TechnicalValue v-if="editTarget" :value="editTarget.id" /></UFormField><p v-if="editTarget">ایجاد: {{ formatDateTime(editTarget.created_at) }} · آخرین تغییر: {{ formatDateTime(editTarget.updated_at) }}</p></form></template><template #footer><UButton color="neutral" variant="ghost" :disabled="pending" @click="editTarget = null">انصراف</UButton><UButton :loading="pending" @click="saveIdentity">ذخیره</UButton></template></UModal>
  <UModal :open="!!passwordTarget" title="تغییر رمز عبور" @update:open="value => { if (!value && !pending) { passwordTarget = null; password = '' } }"><template #body><p>رمز جدید برای {{ passwordTarget?.display_name }} تنظیم می‌شود. هیچ پیوند یا ایمیل بازیابی ارسال نمی‌شود.</p><UFormField label="رمز عبور جدید" :error="fields.password?.[0]"><UInput v-model="password" dir="ltr" type="password" autocomplete="new-password" :disabled="pending" /></UFormField></template><template #footer><UButton color="neutral" variant="ghost" :disabled="pending" @click="passwordTarget = null; password = ''">انصراف</UButton><UButton :loading="pending" :disabled="password.length < 12" @click="savePassword">تغییر رمز</UButton></template></UModal>
  <UModal :open="!!authorityTarget" :title="authorityTarget?.is_system_admin ? 'لغو مدیر سراسری' : 'اعطای مدیر سراسری'" @update:open="value => { if (!value && !pending) authorityTarget = null }"><template #body><p v-if="authorityTarget?.is_system_admin">مدیریت سراسری بلافاصله پایان می‌یابد؛ عضویت‌ها و نقش‌های پروژه‌ای حفظ می‌شوند.</p><p v-else>این دسترسی، مدیریت همهٔ پروژه‌ها و کاربران را بدون عضویت پروژه می‌دهد؛ اختیار QA یا توسعه ایجاد نمی‌کند.</p><UAlert v-if="authorityTarget?.id === session.user.value?.id" color="warning" variant="subtle" description="این اقدام روی حساب شما اعمال می‌شود و ممکن است دسترسی فعلی را از بین ببرد." /></template><template #footer><UButton color="neutral" variant="ghost" :disabled="pending" @click="authorityTarget = null">انصراف</UButton><UButton :color="authorityTarget?.is_system_admin ? 'error' : 'primary'" :loading="pending" @click="changeAuthority">تأیید</UButton></template></UModal>
  <UModal :open="!!deactivateTarget || !!remediation" title="غیرفعال‌کردن کاربر" :description="remediation?.message" @update:open="value => { if (!value && !pending) { deactivateTarget = null; remediation = null } }"><template #body><template v-if="remediation"><p>واگذاری‌ها ممکن است در چند پروژه باشند. یک راهبرد برای همه اعمال می‌شود و امکان انتخاب جداگانه برای هر باگ نیست.</p><UFormField label="شناسهٔ توسعه‌دهندهٔ جایگزین" :error="fields['remediation.reassign_to']?.[0]"><UInput v-model="replacementId" dir="ltr" placeholder="UUID" :disabled="pending" /></UFormField></template><p v-else>رکورد و تاریخچه حفظ می‌شوند؛ عضویت‌ها حذف نمی‌شوند و واگذاری‌های باز ممکن است نیازمند اصلاح باشند.</p></template><template #footer><UButton color="neutral" variant="ghost" :disabled="pending" @click="deactivateTarget = null; remediation = null">انصراف</UButton><UButton v-if="remediation && replacementId" :loading="pending" @click="deactivate({ reassign_to: replacementId })">واگذاری همه به جایگزین</UButton><UButton color="error" :loading="pending" @click="deactivate(remediation ? { unassign: true } : undefined)">{{ remediation ? 'لغو تخصیص همه' : 'غیرفعال‌کردن' }}</UButton></template></UModal>
</template>

<style scoped>
.users-page{padding:1.5rem}.users-toolbar{align-items:center;border-bottom:1px solid var(--ui-border);display:flex;gap:1rem;justify-content:space-between;padding-bottom:1rem}.users-toolbar__controls,.users-toolbar__end{align-items:center;display:flex;gap:.5rem}.users-toolbar__controls :deep(input){min-width:20rem}.users-range,.users-table__none{color:var(--ui-text-muted);font-size:.76rem}.users-loading,.users-state{display:grid;gap:.65rem;margin-top:1.25rem}.users-state h2{font-size:1rem;margin:0}.users-state--blocked{padding:1.5rem}.users-table-wrap{margin-top:1.25rem}.users-table{border-collapse:collapse;table-layout:fixed;width:100%}.users-table th{color:var(--ui-text-muted);font-size:.72rem;font-weight:650;padding:.65rem .75rem;text-align:start}.users-table td{border-top:1px solid var(--ui-border);font-size:.82rem;padding:.8rem .75rem;vertical-align:top}.users-table th:nth-child(1){width:24%}.users-table th:nth-child(2){width:18%}.users-table th:nth-child(3){width:16%}.users-table th:nth-child(4){width:10%}.users-table th:nth-child(5){width:15%}.users-table th:nth-child(6){width:17%}.users-table__identity{display:grid;gap:.2rem}.users-table__inactive td{color:var(--ui-text-muted)}.users-table__actions{display:flex;flex-wrap:wrap;gap:.2rem}.users-pagination{align-items:center;border-top:1px solid var(--ui-border);display:flex;gap:.75rem;justify-content:center;margin-top:1rem;padding-top:1rem}.users-form{display:grid;gap:1rem}@media(max-width:767px){.users-page{padding:1rem}.users-toolbar{align-items:stretch;flex-direction:column}.users-toolbar__controls,.users-toolbar__end{justify-content:space-between}.users-toolbar__controls :deep(input){min-width:0}.users-table th:nth-child(2),.users-table td:nth-child(2),.users-table th:nth-child(5),.users-table td:nth-child(5){display:none}.users-table th:nth-child(1){width:32%}.users-table th:nth-child(3){width:20%}.users-table th:nth-child(4){width:15%}.users-table th:nth-child(6){width:33%}.users-table__actions{flex-direction:column}.users-table__actions :deep(button){justify-content:flex-start;min-height:2.25rem}}
</style>
